#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLegacyLogin: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = LegacyLogin

    public static func lift(_ handle: UInt64) throws -> LegacyLogin {
        return LegacyLogin(unsafeFromHandle: handle)
    }

    public static func lower(_ value: LegacyLogin) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LegacyLogin {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: LegacyLogin, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLegacyLogin_lift(_ handle: UInt64) throws -> LegacyLogin {
    return try FfiConverterTypeLegacyLogin.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLegacyLogin_lower(_ value: LegacyLogin) -> UInt64 {
    return FfiConverterTypeLegacyLogin.lower(value)
}






/**
 * The open title of one account.
 */
public protocol LegacyPlaybackProtocol: AnyObject, Sendable {
    
    /**
     * `Kern.audioFromHand`.
     */
    func audioFromHand(audio: String, id: Int64, memory: String)  -> String
    
    /**
     * `Kern.backgroundReport`.
     */
    func backgroundReport(position: Double, paused: Bool) 
    
    /**
     * `Kern.chapterBar`.
     */
    func chapterBar(duration: Double, width: Double, minWidth: Double, gap: Double)  -> String
    
    /**
     * `Kern.chapterLoad`.
     */
    func chapterLoad()  -> Int64
    
    /**
     * `Kern.chapterName`.
     */
    func chapterName(at: Double)  -> String
    
    /**
     * `Kern.chapterPiece`.
     */
    func chapterPiece(share: Double, duration: Double, width: Double, minWidth: Double)  -> Int64
    
    /**
     * `Kern.controlsChanged`.
     */
    func controlsChanged(opened: Bool)  -> String
    
    /**
     * `Kern.displayTime`.
     */
    func displayTime(position: Double, atPush: Bool)  -> Double
    
    /**
     * `Kern.episodePrepare`.
     */
    func episodePrepare() async throws 
    
    /**
     * `Kern.episodeSwitch`.
     */
    func episodeSwitch(id: String, position: Double) async throws  -> String
    
    /**
     * `Kern.firstFrameVideoCodec`.
     */
    func firstFrameVideoCodec()  -> String
    
    /**
     * `Kern.jumpReported`.
     */
    func jumpReported(target: Double)  -> String
    
    /**
     * The report lines since the last pickup (`Kern.logFetch`).
     */
    func logFetch()  -> String
    
    /**
     * `Kern.playbackLookUp`: next episode and sections of a stored file from the server; empty when nothing changed.
     */
    func lookUp() async throws  -> String
    
    /**
     * `Kern.nextAutomaticSet`.
     */
    func nextAutomaticSet(on: Bool) 
    
    /**
     * `Kern.offeringClose`.
     */
    func offeringClose()  -> Bool
    
    /**
     * `Kern.offeringPressed`.
     */
    func offeringPressed() 
    
    /**
     * `Kern.playbackOpen`.
     */
    func `open`(id: String, sourceId: String) async throws  -> String
    
    /**
     * `Kern.playbackFromTheSlab`: a stored file plays before any server.
     */
    func openSlab(entries: String, path: String, image: String) throws  -> String
    
    /**
     * `Kern.openSubtitle`.
     */
    func openSubtitle(subtitle: String)  -> Int64
    
    /**
     * `Kern.playbackEnd`.
     */
    func playbackEnd(position: Double) async throws  -> String
    
    /**
     * `Kern.playbackPoint`.
     */
    func playbackPoint(since: Double) 
    
    /**
     * `Kern.playbackSelection`.
     */
    func playbackSelection(alwaysDirectPlay: Bool, megabit: Int64) 
    
    /**
     * `Kern.playbackTick`.
     */
    func playbackTick(duration: Double, position: Double, showsImage: Bool, running: Bool, hasAudioTracks: Bool, atPush: Bool, autoSkip: Bool)  -> String
    
    /**
     * `Kern.prebufferDue`.
     */
    func prebufferDue(position: Double, duration: Double, networkFavorable: Bool)  -> Bool
    
    /**
     * `Kern.qualitySwitch`.
     */
    func qualitySwitch(position: Double) async throws  -> String
    
    /**
     * `Kern.resumeTarget`.
     */
    func resumeTarget(position: Double, inGroup: Bool)  -> Double
    
    /**
     * `Kern.runStateReported`.
     */
    func runStateReported(running: Bool, position: Double) 
    
    /**
     * The downloads list and the network state: where "next episode" comes from.
     */
    func setDownloads(list: String, withoutNetwork: Bool) 
    
    /**
     * The device has no Dolby Vision decoder: Dolby Vision profile 5 is planned as a server transcode.
     */
    func setNoDolbyVisionDecoder(on: Bool) 
    
    /**
     * Tracks sent with the title from another client.
     */
    func setOrdered(itemId: String, audio: Int64?, subtitle: Int64?) 
    
    /**
     * `Kern.subtitleLookReport`: whether the server hands ASS out as SRT.
     */
    func setServerExtractsText(on: Bool) 
    
    /**
     * A group plays without a next episode.
     */
    func setWithoutNext(on: Bool) 
    
    /**
     * The stops since the last pickup (for the download's watch state).
     */
    func stopsTake()  -> [LegacyStopped]
    
    /**
     * `Kern.subtitleAttributeSet`.
     */
    func subtitleAttributeSet(index: Int64, attribute: String) 
    
    /**
     * `Kern.subtitleFiles`.
     */
    func subtitleFiles()  -> String
    
    /**
     * `Kern.subtitleFromHand`.
     */
    func subtitleFromHand(subtitle: String, id: Int64, memory: String)  -> String
    
    /**
     * `Kern.techFixed`.
     */
    func techFixed(measure: Bool)  -> String
    
    /**
     * The frame rate (-1: none) and the average bytes per second (-1: none) of the open file, for the tech badge's measurement.
     */
    func techSource()  -> [Double]
    
    /**
     * `Kern.techTick` (the eleven VLC counters in the old order, then position and whether it runs).
     */
    func techTick(hasRead: Int64, unpacked: Int64, shown: Int64, discarded: Int64, videoBlocks: Int64, audioBlocks: Int64, audioPlay: Int64, audioLost: Int64, damaged: Int64, jumps: Int64, spot: Double, running: Bool)  -> String
    
    /**
     * `Kern.trackNames`.
     */
    func trackNames(audio: String, subtitle: String)  -> String
    
    /**
     * `Kern.tracksSelect`.
     */
    func tracksSelect(audio: String, subtitle: String, audioNow: Int64, audioWish: String, subtitlePreference: String, automatic: Bool, audioMemory: String, subtitleMemory: String)  -> String
    
    /**
     * `Kern.trickplayAddress`.
     */
    func trickplayAddress(width: Int64, sheet: Int64)  -> String
    
    /**
     * `Kern.trickplayDetail`.
     */
    func trickplayDetail()  -> String
    
}
/**
 * The open title of one account.
 */
