#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLegacyPlayback: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = LegacyPlayback

    public static func lift(_ handle: UInt64) throws -> LegacyPlayback {
        return LegacyPlayback(unsafeFromHandle: handle)
    }

    public static func lower(_ value: LegacyPlayback) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LegacyPlayback {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: LegacyPlayback, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLegacyPlayback_lift(_ handle: UInt64) throws -> LegacyPlayback {
    return try FfiConverterTypeLegacyPlayback.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeLegacyPlayback_lower(_ value: LegacyPlayback) -> UInt64 {
    return FfiConverterTypeLegacyPlayback.lower(value)
}






/**
 * Title, series and person pages of one Plex account.
 */
public protocol LegacyPlexDetailProtocol: AnyObject, Sendable {
    
