/**
 * The thin driver behind the player (AetherDriver, AVPlayer, VLC on Apple). Commands return
 * at once; results come back as events.
 */
public protocol PlayerEngine: AnyObject, Sendable {
    
    func load(request: PlayerLoad) 
    
    func play() 
    
    func pause() 
    
    func seek(seconds: Double) 
    
    func setRate(tempo: Float) 
    
    func setVolume(percent: UInt8) 
    
    func setAudioDelay(milliseconds: Int32) 
    
    /**
     * Subtitle delay in milliseconds (positive: later); the host shifts the cues it draws.
     */
    func setSubtitleDelay(milliseconds: Int32) 
    
    /**
     * `false` if the engine has no such track.
     */
    func selectAudio(serverIndex: Int32)  -> Bool
    
    /**
     * `-1` off.
     */
    func selectSubtitle(serverIndex: Int32)  -> PlayerSubtitleRoute
    
    func setFill(on: Bool) 
    
    func place(rect: PlayerRect) 
    
    func stop(resetDisplay: Bool) 
    
    func pip(command: PlayerPip) 
    
}
