// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfacePlexPinListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfacePlexPinListener = UniffiVTableCallbackInterfacePlexPinListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypePlexPinListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface PlexPinListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypePlexPinListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface PlexPinListener: handle missing in uniffiClone")
            }
        },
        rest: { (
            uniffiHandle: UInt64,
            seconds: Int64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypePlexPinListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.rest(
                     seconds: try FfiConverterInt64.lift(seconds)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfacePlexPinListener> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfacePlexPinListener>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitPlexPinListener() {
    uniffi_swiftly_uniffi_fn_init_callback_vtable_plexpinlistener(UniffiCallbackInterfacePlexPinListener.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePlexPinListener: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<PlexPinListener>()

    typealias FfiType = UInt64
    typealias SwiftType = PlexPinListener

    public static func lift(_ handle: UInt64) throws -> PlexPinListener {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return PlexPinListenerImpl(unsafeFromHandle: handle)
