// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceQuickConnectListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceQuickConnectListener = UniffiVTableCallbackInterfaceQuickConnectListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeQuickConnectListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface QuickConnectListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeQuickConnectListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface QuickConnectListener: handle missing in uniffiClone")
            }
        },
        rest: { (
            uniffiHandle: UInt64,
            seconds: Int64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeQuickConnectListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.rest(
                     seconds: try FfiConverterInt64.lift(seconds)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceQuickConnectListener> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceQuickConnectListener>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitQuickConnectListener() {
    uniffi_swiftly_uniffi_fn_init_callback_vtable_quickconnectlistener(UniffiCallbackInterfaceQuickConnectListener.vtablePtr)
}

