// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceSyncPlayHost {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceSyncPlayHost = UniffiVTableCallbackInterfaceSyncPlayHost(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeSyncPlayHost.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface SyncPlayHost: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeSyncPlayHost.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface SyncPlayHost: handle missing in uniffiClone")
            }
        },
        playerStep: { (
            uniffiHandle: UInt64,
            step: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeSyncPlayHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.playerStep(
                     step: try FfiConverterTypeSyncPlayStep_lift(step)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        loadTitle: { (
            uniffiHandle: UInt64,
            title: RustBuffer,
            since: Double,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeSyncPlayHost.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.loadTitle(
                     title: try FfiConverterString.lift(title),
                     since: try FfiConverterDouble.lift(since)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceSyncPlayHost> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceSyncPlayHost>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitSyncPlayHost() {
    uniffi_swiftly_uniffi_fn_init_callback_vtable_syncplayhost(UniffiCallbackInterfaceSyncPlayHost.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSyncPlayHost: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<SyncPlayHost>()

    typealias FfiType = UInt64
    typealias SwiftType = SyncPlayHost

    public static func lift(_ handle: UInt64) throws -> SyncPlayHost {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return SyncPlayHostImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: SyncPlayHost) -> UInt64 {
         if let rustImpl = value as? SyncPlayHostImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SyncPlayHost {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: SyncPlayHost, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


