/**
 * One request for the host to send.
 */
public struct NetRequest: Equatable, Hashable {
    /**
     * Method.
     */
    public var method: NetMethod
    /**
     * Complete address.
     */
    public var url: String
    /**
     * Header fields in order.
     */
    public var headers: [NetHeader]
    /**
     * Body, if any.
     */
    public var body: Data?
    /**
     * Timeout for this one request in milliseconds (replaces the session's), if set.
     */
    public var timeoutMs: UInt64?
    /**
     * Refuse a redirect that would change the method (POST turned into GET) and return the 3xx
     * answer instead (`KeepPostRedirects`; the Seerr sign-in sets it).
     */
    public var keepMethod: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Method.
         */method: NetMethod, 
        /**
         * Complete address.
         */url: String, 
        /**
         * Header fields in order.
         */headers: [NetHeader], 
        /**
         * Body, if any.
         */body: Data?, 
        /**
         * Timeout for this one request in milliseconds (replaces the session's), if set.
         */timeoutMs: UInt64?, 
        /**
         * Refuse a redirect that would change the method (POST turned into GET) and return the 3xx
         * answer instead (`KeepPostRedirects`; the Seerr sign-in sets it).
         */keepMethod: Bool = false) {
        self.method = method
        self.url = url
        self.headers = headers
        self.body = body
        self.timeoutMs = timeoutMs
        self.keepMethod = keepMethod
    }

    

    
}

