/**
 * A playable title: the plan (address, headers, session ids) and the starting tracks.
 */
public struct PlayerStart: Equatable, Hashable {
    public var itemId: String
    public var title: String
    public var playSessionId: String?
    public var mediaSourceId: String?
    public var method: PlayerMethod
    public var url: String
    public var headers: [PlayerHeader]
    public var streams: [PlayerStream]
    public var runtime: Double
    public var startAt: Double
    public var audioIndex: Int64?
    public var subtitleIndex: Int64
    public var next: PlayerNext?
    public var seriesId: String?
    /**
     * Key of the track memory; `None` remembers nothing.
     */
    public var trackTitle: String?
    public var downloaded: Bool
    public var softwareDecode: Bool
    public var frameRateMatch: Bool
    /**
     * How much the engine buffers before the picture appears (`pufferstufe`).
     */
    public var bufferLevel: PlayerBuffer
    /**
     * External subtitle files (Jellyfin stream index, address, MD5 of the address).
     */
    public var subtitleFiles: [PlayerSubtitleFile]
    /**
     * First engine track id given to external files.
     */
    public var externalTrackIdBase: Int64
    /**
     * The chosen version as the server's `MediaSource` JSON (`PlayReady.source_json`). The track rules read the
     * whole streams from it (`IsOriginal`, `IsExternal`, titles, Dolby Vision fields, `DisplayTitle`), which
     * `streams` cannot carry; without it (or when it does not parse) the player falls back to `streams`.
     * `PlayerVm::source_json` hands it back.
     */
    public var sourceJson: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(itemId: String, title: String, playSessionId: String?, mediaSourceId: String?, method: PlayerMethod, url: String, headers: [PlayerHeader], streams: [PlayerStream], runtime: Double, startAt: Double, audioIndex: Int64?, subtitleIndex: Int64, next: PlayerNext?, seriesId: String?, 
        /**
         * Key of the track memory; `None` remembers nothing.
         */trackTitle: String?, downloaded: Bool, softwareDecode: Bool, frameRateMatch: Bool, 
        /**
         * How much the engine buffers before the picture appears (`pufferstufe`).
         */bufferLevel: PlayerBuffer, 
        /**
         * External subtitle files (Jellyfin stream index, address, MD5 of the address).
         */subtitleFiles: [PlayerSubtitleFile], 
        /**
         * First engine track id given to external files.
         */externalTrackIdBase: Int64, 
        /**
         * The chosen version as the server's `MediaSource` JSON (`PlayReady.source_json`). The track rules read the
         * whole streams from it (`IsOriginal`, `IsExternal`, titles, Dolby Vision fields, `DisplayTitle`), which
         * `streams` cannot carry; without it (or when it does not parse) the player falls back to `streams`.
         * `PlayerVm::source_json` hands it back.
         */sourceJson: String? = nil) {
        self.itemId = itemId
        self.title = title
        self.playSessionId = playSessionId
        self.mediaSourceId = mediaSourceId
        self.method = method
        self.url = url
        self.headers = headers
        self.streams = streams
        self.runtime = runtime
        self.startAt = startAt
        self.audioIndex = audioIndex
        self.subtitleIndex = subtitleIndex
        self.next = next
        self.seriesId = seriesId
        self.trackTitle = trackTitle
        self.downloaded = downloaded
        self.softwareDecode = softwareDecode
        self.frameRateMatch = frameRateMatch
        self.bufferLevel = bufferLevel
        self.subtitleFiles = subtitleFiles
        self.externalTrackIdBase = externalTrackIdBase
        self.sourceJson = sourceJson
    }

    

    
}

