 * What a host tells the session machine (the screen's own steps are fed by `LoginModel`).
 */

public enum AccountSessionEvent: Equatable, Hashable {
    
    case connect(server: String
    )
    case reachable
    case unreachable(reason: String
    )
    case beginSignIn(method: AccountSignInMethod
    )
    case signedIn(account: String
    )
    case signInRefused
    case cancelled
    case switchTo(to: String
    )
    case switchDone(account: String
    )
    case switchFailed
    case signOut
    case revoked(account: String
    )





}

#if compiler(>=6)
extension AccountSessionEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAccountSessionEvent: FfiConverterRustBuffer {
    typealias SwiftType = AccountSessionEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AccountSessionEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .connect(server: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .reachable
        
        case 3: return .unreachable(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .beginSignIn(method: try FfiConverterTypeAccountSignInMethod.read(from: &buf)
        )
        
        case 5: return .signedIn(account: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .signInRefused
        
        case 7: return .cancelled
        
        case 8: return .switchTo(to: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .switchDone(account: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .switchFailed
        
        case 11: return .signOut
        
        case 12: return .revoked(account: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AccountSessionEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .connect(server):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(server, into: &buf)
            
        
        case .reachable:
            writeInt(&buf, Int32(2))
        
        
        case let .unreachable(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .beginSignIn(method):
            writeInt(&buf, Int32(4))
            FfiConverterTypeAccountSignInMethod.write(method, into: &buf)
            
        
        case let .signedIn(account):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(account, into: &buf)
            
        
        case .signInRefused:
            writeInt(&buf, Int32(6))
        
        
        case .cancelled:
            writeInt(&buf, Int32(7))
        
        
        case let .switchTo(to):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(to, into: &buf)
            
        
        case let .switchDone(account):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(account, into: &buf)
            
        
        case .switchFailed:
            writeInt(&buf, Int32(10))
        
        
        case .signOut:
            writeInt(&buf, Int32(11))
        
        
        case let .revoked(account):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(account, into: &buf)
            
        }
    }
}


