    case signedOut
    case connecting(server: String, from: String?
    )
    case needsLogin(server: String, from: String?
    )
    case signingIn(server: String, method: AccountSignInMethod, from: String?
    )
    case ready(account: String
    )
    case switching(from: String, to: String
    )
    case failed(server: String, reason: String
    )





}

