public struct FfiConverterTypeAccountSessionState: FfiConverterRustBuffer {
    typealias SwiftType = AccountSessionState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AccountSessionState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .signedOut
        
        case 2: return .connecting(server: try FfiConverterString.read(from: &buf), from: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 3: return .needsLogin(server: try FfiConverterString.read(from: &buf), from: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .signingIn(server: try FfiConverterString.read(from: &buf), method: try FfiConverterTypeAccountSignInMethod.read(from: &buf), from: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 5: return .ready(account: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .switching(from: try FfiConverterString.read(from: &buf), to: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .failed(server: try FfiConverterString.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AccountSessionState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .signedOut:
            writeInt(&buf, Int32(1))
        
        
        case let .connecting(server,from):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(server, into: &buf)
            FfiConverterOptionString.write(from, into: &buf)
            
        
        case let .needsLogin(server,from):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(server, into: &buf)
            FfiConverterOptionString.write(from, into: &buf)
            
        
        case let .signingIn(server,method,from):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(server, into: &buf)
            FfiConverterTypeAccountSignInMethod.write(method, into: &buf)
            FfiConverterOptionString.write(from, into: &buf)
            
        
        case let .ready(account):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(account, into: &buf)
            
        
        case let .switching(from,to):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(from, into: &buf)
            FfiConverterString.write(to, into: &buf)
            
        
        case let .failed(server,reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(server, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
