/**
 * The whole queue (`swiftly_downloads::QueuePhase`).
 */

public enum DownloadQueuePhase: Equatable, Hashable {
    
    case empty
    case running(waiting: UInt64
    )
    case ready(waiting: UInt64
    )
    case offline(waiting: UInt64
    )
    case paused(paused: UInt64
    )
    case idle(failed: UInt64
    )
    case broken(running: UInt64
    )





}

#if compiler(>=6)
extension DownloadQueuePhase: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDownloadQueuePhase: FfiConverterRustBuffer {
    typealias SwiftType = DownloadQueuePhase

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DownloadQueuePhase {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .empty
        
        case 2: return .running(waiting: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 3: return .ready(waiting: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 4: return .offline(waiting: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 5: return .paused(paused: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 6: return .idle(failed: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 7: return .broken(running: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DownloadQueuePhase, into buf: inout [UInt8]) {
        switch value {
        
        
        case .empty:
            writeInt(&buf, Int32(1))
        
        
        case let .running(waiting):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(waiting, into: &buf)
            
        
        case let .ready(waiting):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(waiting, into: &buf)
            
        
        case let .offline(waiting):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(waiting, into: &buf)
            
        
        case let .paused(paused):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(paused, into: &buf)
            
        
        case let .idle(failed):
            writeInt(&buf, Int32(6))
            FfiConverterUInt64.write(failed, into: &buf)
            
        
        case let .broken(running):
            writeInt(&buf, Int32(7))
            FfiConverterUInt64.write(running, into: &buf)
            
        }
    }
}


