public enum DownloadsIntent: Equatable, Hashable {
    
    case start(items: [DownloadRequest], 
        /**
         * More images than the requests' own (series poster and header).
         */images: [DownloadImage], checkSpace: Bool
    )
    case pause(id: String
    )
    case resume(id: String
    )
    case cancel(id: String
    )
    case delete(ids: [String]
    )
    case pauseAll
    case deleteAll
    case onlyOverWlan(on: Bool
    )
    case nextAuto(on: Bool
    )
    /**
     * Sign in (or out with `None`); the core reads the stored list itself.
     */
    case signIn(account: String?, client: Bool
    )
    case tick
    /**
     * The path monitor was stopped (the feature is switched off).
     */
    case networkObserveStopped
    case networkChanged(wlan: Bool, none: Bool
    )
    case spaceChanged(bytes: Int64
    )
    case addressReady(id: String, generation: Int64, address: String
    )
    case addressFailed(id: String, generation: Int64, reason: String
    )
    case transferProgress(id: String, generation: Int64, file: String, loaded: Int64, total: Int64, now: Double
    )
    case transferFinished(id: String, generation: Int64, file: String, worked: Bool, realSize: Int64?
    )
    case transferFailed(id: String, generation: Int64, file: String, reason: String, resume: Data?
    )
    case resumeData(id: String, generation: Int64, data: Data
    )
    case runningTransfers(found: [RunningTransferInfo]
    )
    /**
     * Answer to `fetch_sections`.
     */
    case sectionsFetched(id: String, sections: [PlayerSection]
    )
    /**
     * Answer to `fetch_subtitles`: `ok` once every subtitle file and `info.json` are written.
     */
    case subtitlesFetched(id: String, ok: Bool
    )
    /**
     * A playback was recorded on this device (also offline): the list shows the check mark and
     * the remembered position, and the next episode is queued when the rules want it.
     */
    case playbackRemembered(id: String, ticks: Int64, now: Double
    )
    /**
     * What the server says about the titles: `available` are the ids it answered with.
     */
    case serverFollow(available: [String], states: [DownloadWatchState]
    )
    /**
     * Every finished title without stored sections asks again.
     */
    case sectionsCatchUp
    /**
     * Every title with a pending successor looks it up again.
     */
    case smartCatchUp
    /**
     * Answer to `lookup_successor`: the server's `Items` JSON of the series' episodes (`None`:
     * no answer), the landscape image address of the next episode, and the clock (Unix seconds).
     */
    case successorFound(id: String, episodesJson: Data?, image: String?, now: Double
    )





}

#if compiler(>=6)
extension DownloadsIntent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDownloadsIntent: FfiConverterRustBuffer {
    typealias SwiftType = DownloadsIntent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DownloadsIntent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .start(items: try FfiConverterSequenceTypeDownloadRequest.read(from: &buf), images: try FfiConverterSequenceTypeDownloadImage.read(from: &buf), checkSpace: try FfiConverterBool.read(from: &buf)
        )
        
        case 2: return .pause(id: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .resume(id: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .cancel(id: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .delete(ids: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 6: return .pauseAll
        
        case 7: return .deleteAll
        
        case 8: return .onlyOverWlan(on: try FfiConverterBool.read(from: &buf)
        )
        
        case 9: return .nextAuto(on: try FfiConverterBool.read(from: &buf)
        )
        
        case 10: return .signIn(account: try FfiConverterOptionString.read(from: &buf), client: try FfiConverterBool.read(from: &buf)
        )
        
        case 11: return .tick
        
        case 12: return .networkObserveStopped
        
        case 13: return .networkChanged(wlan: try FfiConverterBool.read(from: &buf), none: try FfiConverterBool.read(from: &buf)
        )
        
        case 14: return .spaceChanged(bytes: try FfiConverterInt64.read(from: &buf)
        )
        
        case 15: return .addressReady(id: try FfiConverterString.read(from: &buf), generation: try FfiConverterInt64.read(from: &buf), address: try FfiConverterString.read(from: &buf)
        )
        
        case 16: return .addressFailed(id: try FfiConverterString.read(from: &buf), generation: try FfiConverterInt64.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        case 17: return .transferProgress(id: try FfiConverterString.read(from: &buf), generation: try FfiConverterInt64.read(from: &buf), file: try FfiConverterString.read(from: &buf), loaded: try FfiConverterInt64.read(from: &buf), total: try FfiConverterInt64.read(from: &buf), now: try FfiConverterDouble.read(from: &buf)
        )
        
        case 18: return .transferFinished(id: try FfiConverterString.read(from: &buf), generation: try FfiConverterInt64.read(from: &buf), file: try FfiConverterString.read(from: &buf), worked: try FfiConverterBool.read(from: &buf), realSize: try FfiConverterOptionInt64.read(from: &buf)
        )
        
        case 19: return .transferFailed(id: try FfiConverterString.read(from: &buf), generation: try FfiConverterInt64.read(from: &buf), file: try FfiConverterString.read(from: &buf), reason: try FfiConverterString.read(from: &buf), resume: try FfiConverterOptionData.read(from: &buf)
        )
        
        case 20: return .resumeData(id: try FfiConverterString.read(from: &buf), generation: try FfiConverterInt64.read(from: &buf), data: try FfiConverterData.read(from: &buf)
        )
        
        case 21: return .runningTransfers(found: try FfiConverterSequenceTypeRunningTransferInfo.read(from: &buf)
        )
        
        case 22: return .sectionsFetched(id: try FfiConverterString.read(from: &buf), sections: try FfiConverterSequenceTypePlayerSection.read(from: &buf)
        )
        
        case 23: return .subtitlesFetched(id: try FfiConverterString.read(from: &buf), ok: try FfiConverterBool.read(from: &buf)
        )
        
        case 24: return .playbackRemembered(id: try FfiConverterString.read(from: &buf), ticks: try FfiConverterInt64.read(from: &buf), now: try FfiConverterDouble.read(from: &buf)
        )
        
        case 25: return .serverFollow(available: try FfiConverterSequenceString.read(from: &buf), states: try FfiConverterSequenceTypeDownloadWatchState.read(from: &buf)
        )
        
        case 26: return .sectionsCatchUp
        
        case 27: return .smartCatchUp
        
        case 28: return .successorFound(id: try FfiConverterString.read(from: &buf), episodesJson: try FfiConverterOptionData.read(from: &buf), image: try FfiConverterOptionString.read(from: &buf), now: try FfiConverterDouble.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DownloadsIntent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .start(items,images,checkSpace):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeDownloadRequest.write(items, into: &buf)
            FfiConverterSequenceTypeDownloadImage.write(images, into: &buf)
            FfiConverterBool.write(checkSpace, into: &buf)
            
        
        case let .pause(id):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .resume(id):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .cancel(id):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(id, into: &buf)
            
        
        case let .delete(ids):
            writeInt(&buf, Int32(5))
            FfiConverterSequenceString.write(ids, into: &buf)
            
        
        case .pauseAll:
            writeInt(&buf, Int32(6))
        
        
        case .deleteAll:
            writeInt(&buf, Int32(7))
        
        
        case let .onlyOverWlan(on):
            writeInt(&buf, Int32(8))
            FfiConverterBool.write(on, into: &buf)
            
        
        case let .nextAuto(on):
            writeInt(&buf, Int32(9))
            FfiConverterBool.write(on, into: &buf)
            
        
        case let .signIn(account,client):
            writeInt(&buf, Int32(10))
            FfiConverterOptionString.write(account, into: &buf)
            FfiConverterBool.write(client, into: &buf)
            
        
        case .tick:
            writeInt(&buf, Int32(11))
        
        
        case .networkObserveStopped:
            writeInt(&buf, Int32(12))
        
        
        case let .networkChanged(wlan,none):
            writeInt(&buf, Int32(13))
            FfiConverterBool.write(wlan, into: &buf)
            FfiConverterBool.write(none, into: &buf)
            
        
        case let .spaceChanged(bytes):
            writeInt(&buf, Int32(14))
            FfiConverterInt64.write(bytes, into: &buf)
            
        
        case let .addressReady(id,generation,address):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(id, into: &buf)
            FfiConverterInt64.write(generation, into: &buf)
            FfiConverterString.write(address, into: &buf)
            
        
        case let .addressFailed(id,generation,reason):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(id, into: &buf)
            FfiConverterInt64.write(generation, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .transferProgress(id,generation,file,loaded,total,now):
            writeInt(&buf, Int32(17))
            FfiConverterString.write(id, into: &buf)
            FfiConverterInt64.write(generation, into: &buf)
            FfiConverterString.write(file, into: &buf)
            FfiConverterInt64.write(loaded, into: &buf)
            FfiConverterInt64.write(total, into: &buf)
            FfiConverterDouble.write(now, into: &buf)
            
        
        case let .transferFinished(id,generation,file,worked,realSize):
