            FfiConverterOptionInt64.write(realSize, into: &buf)
            
        
        case let .transferFailed(id,generation,file,reason,resume):
            writeInt(&buf, Int32(19))
            FfiConverterString.write(id, into: &buf)
            FfiConverterInt64.write(generation, into: &buf)
            FfiConverterString.write(file, into: &buf)
