/**
 * What follows a further piece.
 */

public enum ForwardNext: Equatable, Hashable {
    
    /**
     * The server did not serve the piece as asked: end the connection.
     */
    case failed
    /**
     * Everything was served.
     */
    case done
    /**
     * Fetch this piece next.
     */
    case piece(
        /**
         * First byte.
         */since: UInt64, 
        /**
         * Last byte.
         */until: UInt64
    )





}

#if compiler(>=6)
extension ForwardNext: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
