    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ForwardNext {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .failed
        
        case 2: return .done
        
        case 3: return .piece(since: try FfiConverterUInt64.read(from: &buf), until: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ForwardNext, into buf: inout [UInt8]) {
        switch value {
        
        
        case .failed:
            writeInt(&buf, Int32(1))
        
        
        case .done:
            writeInt(&buf, Int32(2))
        
        
        case let .piece(since,until):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(since, into: &buf)
            FfiConverterUInt64.write(until, into: &buf)
            
        }
    }
}


