/**
 * What the host does next.
 */

public enum HandoffEffect: Equatable, Hashable {
    
    /**
     * Request all sessions.
     */
    case ask
    /**
     * Report the capabilities again.
     */
    case reportCapabilities
    /**
     * These sessions can be taken over (most recent first); empty clears the badge.
     */
    case offer(sessionIds: [String]
    )
    /**
     * The last answer is the list for "play on".
     */
    case publishSessions
    /**
     * Preload the images of these sessions' items.
     */
    case preload(sessionIds: [String]
    )
    /**
     * Write to the log.
     */
    case log(line: String
    )
    /**
     * Fetch plan, saved item and sessions of the item.
     */
    case prepare(itemId: String
    )
    /**
     * Send the takeover hint.
     */
    case sendHint(sessionId: String
    )
    /**
     * Tell the session to stop.
     */
    case sendStop(sessionId: String
    )
    /**
     * Sleep 100 ms, read the item's saved position, report `Position`.
     */
    case readPosition(itemId: String
    )
    /**
     * Start here.
     */
    case play(itemId: String, since: Double, positionUnreported: Bool, sessionPoint: Double
    )
    /**
     * Show that no plan came.
     */
    case noPlan
    /**
     * Show this error.
     */
    case showError(text: String
    )





}

#if compiler(>=6)
extension HandoffEffect: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHandoffEffect: FfiConverterRustBuffer {
    typealias SwiftType = HandoffEffect

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HandoffEffect {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ask
        
        case 2: return .reportCapabilities
        
        case 3: return .offer(sessionIds: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 4: return .publishSessions
        
        case 5: return .preload(sessionIds: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 6: return .log(line: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .prepare(itemId: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .sendHint(sessionId: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .sendStop(sessionId: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .readPosition(itemId: try FfiConverterString.read(from: &buf)
        )
        
        case 11: return .play(itemId: try FfiConverterString.read(from: &buf), since: try FfiConverterDouble.read(from: &buf), positionUnreported: try FfiConverterBool.read(from: &buf), sessionPoint: try FfiConverterDouble.read(from: &buf)
        )
        
        case 12: return .noPlan
        
        case 13: return .showError(text: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HandoffEffect, into buf: inout [UInt8]) {
        switch value {
        
        
        case .ask:
            writeInt(&buf, Int32(1))
        
        
        case .reportCapabilities:
            writeInt(&buf, Int32(2))
        
        
        case let .offer(sessionIds):
            writeInt(&buf, Int32(3))
            FfiConverterSequenceString.write(sessionIds, into: &buf)
            
        
        case .publishSessions:
            writeInt(&buf, Int32(4))
        
        
        case let .preload(sessionIds):
            writeInt(&buf, Int32(5))
            FfiConverterSequenceString.write(sessionIds, into: &buf)
            
        
        case let .log(line):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(line, into: &buf)
            
        
        case let .prepare(itemId):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(itemId, into: &buf)
            
        
        case let .sendHint(sessionId):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(sessionId, into: &buf)
            
        
        case let .sendStop(sessionId):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(sessionId, into: &buf)
            
        
        case let .readPosition(itemId):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(itemId, into: &buf)
            
        
        case let .play(itemId,since,positionUnreported,sessionPoint):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(itemId, into: &buf)
            FfiConverterDouble.write(since, into: &buf)
            FfiConverterBool.write(positionUnreported, into: &buf)
            FfiConverterDouble.write(sessionPoint, into: &buf)
            
        
        case .noPlan:
            writeInt(&buf, Int32(12))
        
        
        case let .showError(text):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(text, into: &buf)
            
        }
    }
}


