/**
 * What the host reports to the hand-over flow (see `swiftly_playback::handoff_flow`).
 */

public enum HandoffEvent: Equatable, Hashable {
    
    /**
     * Polling starts.
     */
    case start
    /**
     * Polling stops.
     */
    case finish
    /**
     * The timer fired.
     */
    case tick(playerRuns: Bool, signedIn: Bool
    )
    /**
     * The `/Sessions` answer (JSON array) arrived at `now` (seconds since 1970).
     */
    case answered(sessionsJson: Data, now: Double
    )
    /**
     * The sessions request failed.
     */
    case askFailed(error: String
    )
    /**
     * The user chose an offered session.
     */
    case adopt(sessionId: String
    )
    /**
     * Plan, saved item and fresh sessions arrived.
     */
    case prepared(plan: Bool, savedBefore: Int64?, freshPoint: Double?
    )
    /**
     * The hint was sent (`error` set if it failed).
     */
    case hintDone(error: String?
    )
    /**
     * The stop was accepted.
     */
    case stopAccepted
    /**
     * The stop failed.
     */
    case stopFailed(text: String
    )
    /**
     * The item's saved position (ticks) was read.
     */
    case position(ticks: Int64?
    )





}

#if compiler(>=6)
extension HandoffEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHandoffEvent: FfiConverterRustBuffer {
    typealias SwiftType = HandoffEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HandoffEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .start
        
        case 2: return .finish
        
        case 3: return .tick(playerRuns: try FfiConverterBool.read(from: &buf), signedIn: try FfiConverterBool.read(from: &buf)
        )
        
        case 4: return .answered(sessionsJson: try FfiConverterData.read(from: &buf), now: try FfiConverterDouble.read(from: &buf)
        )
        
        case 5: return .askFailed(error: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .adopt(sessionId: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .prepared(plan: try FfiConverterBool.read(from: &buf), savedBefore: try FfiConverterOptionInt64.read(from: &buf), freshPoint: try FfiConverterOptionDouble.read(from: &buf)
        )
        
        case 8: return .hintDone(error: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 9: return .stopAccepted
        
        case 10: return .stopFailed(text: try FfiConverterString.read(from: &buf)
        )
        
        case 11: return .position(ticks: try FfiConverterOptionInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HandoffEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .start:
            writeInt(&buf, Int32(1))
        
        
        case .finish:
            writeInt(&buf, Int32(2))
        
        
        case let .tick(playerRuns,signedIn):
            writeInt(&buf, Int32(3))
            FfiConverterBool.write(playerRuns, into: &buf)
            FfiConverterBool.write(signedIn, into: &buf)
            
        
        case let .answered(sessionsJson,now):
            writeInt(&buf, Int32(4))
            FfiConverterData.write(sessionsJson, into: &buf)
            FfiConverterDouble.write(now, into: &buf)
            
        
        case let .askFailed(error):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(error, into: &buf)
            
        
        case let .adopt(sessionId):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(sessionId, into: &buf)
            
        
        case let .prepared(plan,savedBefore,freshPoint):
            writeInt(&buf, Int32(7))
            FfiConverterBool.write(plan, into: &buf)
            FfiConverterOptionInt64.write(savedBefore, into: &buf)
            FfiConverterOptionDouble.write(freshPoint, into: &buf)
            
        
        case let .hintDone(error):
            writeInt(&buf, Int32(8))
            FfiConverterOptionString.write(error, into: &buf)
            
        
        case .stopAccepted:
            writeInt(&buf, Int32(9))
        
        
        case let .stopFailed(text):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .position(ticks):
            writeInt(&buf, Int32(11))
            FfiConverterOptionInt64.write(ticks, into: &buf)
            
        }
    }
}


