/**
 * Why a request did not get an answer.
 */
public 
enum HttpFailure: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * `NSURLErrorDomain` code (timeout -1001, no host -1003, ...).
     */
    case Network(
        /**
         * The URL error code.
         */code: Int32
    )
    /**
     * TLS failure; the code and the error text sort the reason.
     */
    case Certificate(
        /**
         * The URL error code (-1200 ...).
         */code: Int32, 
        /**
         * The error text, for the reason rules.
         */text: String
    )
    /**
     * The request was cancelled.
     */
    case Cancelled
    /**
     * Anything else.
     */
    case Other(
        /**
         * Developer-readable description.
         */message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension HttpFailure: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHttpFailure: FfiConverterRustBuffer {
    typealias SwiftType = HttpFailure

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HttpFailure {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Network(
            code: try FfiConverterInt32.read(from: &buf)
            )
        case 2: return .Certificate(
            code: try FfiConverterInt32.read(from: &buf), 
            text: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Cancelled
        case 4: return .Other(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HttpFailure, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Network(code):
            writeInt(&buf, Int32(1))
            FfiConverterInt32.write(code, into: &buf)
            
        
        case let .Certificate(code,text):
            writeInt(&buf, Int32(2))
            FfiConverterInt32.write(code, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(3))
        
        
        case let .Other(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


