        switch variant {
        
        case 1: return .ready(ready: try FfiConverterTypePlayReady.read(from: &buf)
        )
        
        case 2: return .choose(itemId: try FfiConverterString.read(from: &buf), versions: try FfiConverterSequenceTypePlayVersion.read(from: &buf), since: try FfiConverterDouble.read(from: &buf)
        )
        
        case 3: return .noSource
        
        case 4: return .versionsFailed
        
        case 5: return .failed(message: try FfiConverterString.read(from: &buf), failure: try FfiConverterTypePlayFailure.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PlayPlanAnswer, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .ready(ready):
            writeInt(&buf, Int32(1))
            FfiConverterTypePlayReady.write(ready, into: &buf)
            
        
        case let .choose(itemId,versions,since):
            writeInt(&buf, Int32(2))
