public enum PlayerEffectOut: Equatable, Hashable {
    
    /**
     * Leave the screen.
     */
    case close
    /**
     * Fetch the plan of this episode, then `load_title`. The old stop is reported already.
     */
    case startEpisode(id: String, fromCard: Bool, since: Double
    )
    /**
     * A subtitle on a transcoded stream: `playPlanOnly(..., subtitle)`, then `loadTitle` at `since`, starting on
     * `subtitle` (`-1` off). The old stop is reported already.
     */
    case reloadForSubtitle(id: String, subtitle: Int64, since: Double
    )
    /**
     * Write `alwaysDirectPlay` / `bitratesLimit`.
     */
    case qualityChosen(directPlay: Bool, limit: Int64
    )
    case forgetPrepared
    /**
     * Rating (`rating`) or Discord prompt after the player is closed.
     */
    case nudge(rating: Bool
    )
    case prepareNext(id: String
    )
    case handOver(subtitle: Int64, reason: String
    )
    /**
     * The stalled stream was reopened at the same position; the engine got its load already.
     */
    case streamRebuilt(position: Double, paused: Bool, reason: String
    )





}

