public enum PlayerEngineEvent: Equatable, Hashable {
    
    case state(state: PlayerEngineState
    )
    case firstFrame
    case clock(position: Double, sourceTime: Double
    )
    case duration(seconds: Double
    )
    case videoSize(width: Double, height: Double
    )
    case tracks(audio: [PlayerTrack], subtitles: [PlayerTrack], activeAudio: Int64?, activeSubtitle: Int64?
    )
    case cues(cues: [PlayerCue]
    )
    /**
     * `dropped`: the source has sound and none of it could be delivered.
     */
    case audioDelivery(dropped: Bool
    )
    case route(route: PlayerRoute
    )
    case pipPossible(on: Bool
    )
    case pipActive(on: Bool
    )
    case pipRestoreUi
    case displayModeSwitch
    case loadFinished(attempt: UInt32
    )
    case loadFailed(attempt: UInt32, message: String, kind: String?
    )
    case startWatchdog(attempt: UInt32
    )
    case seekLanded(target: Double
    )





}

