    case pressOffering
    /**
     * Esc/Menu: closes the card, then a panel, then the controls, then the player.
     */
    case dismiss
    case nextEpisode
    case pip(command: PlayerPip
    )
    case close
    /**
     * `None`: Direct Play; `Some(n)`: a cap of n Mbit/s.
     */
    case quality(limit: Int64?
    )
    case retry
    case enginePlay
    case enginePause
    /**
     * A rebuild after a network change is running: show the last good position.
     */
    case restoring(on: Bool
    )
    case engineSeek(seconds: Double
    )





}

