/**
 * What the series view asks for.
 */

public enum SeriesIntent: Equatable, Hashable {
    
    /**
     * First appearance (and the retry of a failed season list).
     */
    case load
    /**
     * Back from the player.
     */
    case refresh
    /**
     * Another season.
     */
    case selectSeason(
        /**
         * The season id.
         */id: String
    )
    /**
     * Show 40 more rows.
     */
    case moreEpisodes
    /**
     * Fetch the episodes again.
     */
    case retryEpisodes
    /**
     * One episode watched or unwatched.
     */
    case setEpisodeWatched(
        /**
         * The episode id.
         */id: String, 
        /**
         * On or off.
         */on: Bool
    )
    /**
     * Mark the shown season watched.
     */
    case markSeasonWatched
    /**
     * The series watched or unwatched.
     */
    case setWatched(
        /**
         * On or off.
         */on: Bool
    )
    /**
     * The series on the watchlist or off.
     */
    case setWatchlist(
        /**
         * On or off.
         */on: Bool
    )
    /**
     * Close the notice line.
     */
    case dismissMessage
    /**
     * Host settings changed.
     */
    case options(
        /**
         * The settings.
         */options: SeriesOptions
    )
    /**
     * The trailer was asked for.
     */
    case trailer
    /**
     * A menu entry was chosen.
     */
    case menu(
        /**
         * The entry.
         */kind: MenuKind
    )
    /**
     * Another account (or none).
     */
    case accountSwitched(
        /**
         * The account.
         */account: AccountRef?
    )





}

