        switch variant {
        
        case 1: return .load
        
        case 2: return .refresh
        
        case 3: return .selectSeason(id: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .moreEpisodes
        
        case 5: return .retryEpisodes
        
        case 6: return .setEpisodeWatched(id: try FfiConverterString.read(from: &buf), on: try FfiConverterBool.read(from: &buf)
        )
        
        case 7: return .markSeasonWatched
        
        case 8: return .setWatched(on: try FfiConverterBool.read(from: &buf)
        )
        
        case 9: return .setWatchlist(on: try FfiConverterBool.read(from: &buf)
        )
        
        case 10: return .dismissMessage
        
        case 11: return .options(options: try FfiConverterTypeSeriesOptions.read(from: &buf)
        )
        
        case 12: return .trailer
        
        case 13: return .menu(kind: try FfiConverterTypeMenuKind.read(from: &buf)
        )
        
