        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .apply(values: try FfiConverterSequenceTypeSyncSetting.read(from: &buf), changed: try FfiConverterDouble.read(from: &buf)
        )
        
        case 2: return .pushed(changed: try FfiConverterDouble.read(from: &buf)
        )
        
        case 3: return .nothing
        
        case 4: return .unreachable
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SettingsSyncOutcome, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .apply(values,changed):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeSyncSetting.write(values, into: &buf)
            FfiConverterDouble.write(changed, into: &buf)
            
        
        case let .pushed(changed):
            writeInt(&buf, Int32(2))
            FfiConverterDouble.write(changed, into: &buf)
            
        
        case .nothing:
            writeInt(&buf, Int32(3))
        
        
        case .unreachable:
            writeInt(&buf, Int32(4))
        
        }
    }
}


